<?php
require_once __DIR__.'/includes/bootstrap.php';require_patient();$s=$pdo->prepare('SELECT a.*,u.full_name doctor_name,dp.specialty FROM appointments a JOIN users u ON u.id=a.doctor_id JOIN doctor_profiles dp ON dp.user_id=u.id WHERE a.patient_id=? ORDER BY a.appointment_date DESC,a.appointment_time DESC');$s->execute([$_SESSION['user_id']]);$rows=$s->fetchAll();$notice=get_flash();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My appointments | MediConnect</title><link rel="stylesheet" href="assets/css/auth.css"></head><body><main class="dashboard-shell"><header class="dashboard-header"><a class="brand" href="dashboard.php">✚ MediConnect</a><a href="doctor_directory.php">Find doctor</a></header><section class="welcome-panel"><h1>My appointments</h1><p class="muted">Your appointment requests and current statuses.</p></section><?php if($notice):?><div class="alert success"><?=e($notice['message'])?></div><?php endif;?><?php if(!$rows):?><section class="profile-panel">No appointments yet. <a href="doctor_directory.php">Find a doctor</a>.</section><?php endif;?><?php foreach($rows as $a):?><article class="profile-panel"><div class="appointment-heading"><h2><?=e($a['doctor_name'])?></h2><span class="status"><?=e(ucfirst($a['status']))?></span></div><p class="eyebrow"><?=e($a['specialty'])?></p><p><b>Date:</b> <?=e(date('D, j M Y',strtotime($a['appointment_date'])))?></p><p><b>Time:</b> <?=e(date('g:i A',strtotime($a['appointment_time'])))?></p><p><b>Reason:</b> <?=e($a['symptoms'])?></p></article><?php endforeach;?></main></body></html>
